def flat_monthly(principal, rate_pct, months):
    return principal * (1 + rate_pct / 100 * months / 12) / months

result = flat_monthly(120000, 12, 12)

def to_float(s):
    return float(s.replace("₹", "").replace(",", ""))

result = to_float("₹3,450.50")

def bucket(amount):
    if amount < 1000:
        return "S"
    elif amount < 10000:
        return "M"
    else:
        return "L"

result = [bucket(a) for a in [500, 1000, 9999, 15000]]
